
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_kt1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_kt1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.543242207027103e+00, -4.463429067650655e+00, -4.351863449973663e+00, -4.197897845209345e+00, -3.989353958781124e+00, -3.714544305212450e+00, -3.366940274038715e+00, -2.953808011135156e+00, -2.507539036971521e+00, -2.071806954401862e+00, -1.479773003373188e+00, -7.781553221653825e-01, -6.606372040155727e-01, -5.463556455472208e-01, -3.806818206357938e-01, -2.195186086563727e-01, -1.031807096075195e-01, -3.627715616563348e-02, -8.286947268550750e-03, -9.942802931528535e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


